#include <stdio.h>
#include <string.h>
#include <stdbool.h>

char wordList[5005][12];
bool visited[5005];
int queue[5005];
int dist[5005];

bool can_transform(char *a, char *b, int len) {
    int diff = 0;
    for (int i = 0; i < len; i++) {
        if (a[i] != b[i]) { diff++; if (diff > 1) return false; }
    }
    return diff == 1;
}

int main() {
    char begin[12], end[12];
    if (scanf("%s %s", begin, end) != 2) return 0;
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int end_idx = -1;
    for (int i = 0; i < n; i++) {
        scanf("%s", wordList[i]);
        if (strcmp(wordList[i], end) == 0) end_idx = i;
    }
    if (end_idx == -1) { printf("0\n"); return 0; }

    int len = strlen(begin);
    int head = 0, tail = 0;
    for (int i = 0; i < n; i++) {
        if (can_transform(begin, wordList[i], len)) {
            visited[i] = true;
            dist[i] = 2;
            queue[tail++] = i;
        }
    }
    while (head < tail) {
        int cur = queue[head++];
        if (cur == end_idx) {
            printf("%d\n", dist[cur]);
            return 0;
        }
        for (int i = 0; i < n; i++) {
            if (!visited[i] && can_transform(wordList[cur], wordList[i], len)) {
                visited[i] = true;
                dist[i] = dist[cur] + 1;
                queue[tail++] = i;
            }
        }
    }
    printf("0\n");
    return 0;
}
